:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0e0;
  --accent: #6c5ce7;
  --accent-hover: #7f6ff0;
  --done: #00b894;
  --done-hover: #00d2a9;
  --delete: #e74c3c;
  --delete-hover: #ff5e4f;
  --border-radius: 12px;
  --spacing: 16px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing);
}

.card {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: calc(var(--spacing) * 1.5);
  width: 100%;
  max-width: 600px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  text-align: center;
  margin-bottom: calc(var(--spacing) * 1.5);
  color: var(--accent);
  letter-spacing: 0.5px;
}

.habit-form {
  display: flex;
  gap: var(--spacing);
  margin-bottom: calc(var(--spacing) * 1.5);
  flex-wrap: wrap;
}

.habit-form input {
  flex: 1 1 200px;
  padding: 12px 16px;
  border: 2px solid transparent;
  border-radius: var(--border-radius);
  background: var(--bg);
  color: var(--text);
  font-size: 1rem;
  font-family: var(--font);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.habit-form input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.3);
}

.habit-form input::placeholder {
  color: #888;
}

.habit-form button {
  padding: 12px 24px;
  border: none;
  border-radius: var(--border-radius);
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  white-space: nowrap;
}

.habit-form button:hover {
  background: var(--accent-hover);
}

.habit-form button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.habit-form button:active {
  transform: scale(0.97);
}

.habit-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing);
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--bg);
  border-radius: var(--border-radius);
  flex-wrap: wrap;
}

.habit-name {
  flex: 1 1 120px;
  font-weight: 600;
  font-size: 1.1rem;
  word-break: break-word;
}

.day-boxes {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.day-box {
  width: 36px;
  height: 36px;
  border: 2px solid #555;
  border-radius: 8px;
  background: transparent;
  color: var(--text);
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  padding: 0;
  line-height: 1;
}

.day-box:hover {
  border-color: var(--done);
}

.day-box:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.day-box:active {
  transform: scale(0.92);
}

.day-box.done {
  background: var(--done);
  border-color: var(--done);
  color: #fff;
}

.day-box.done:hover {
  background: var(--done-hover);
  border-color: var(--done-hover);
}

.streak {
  font-size: 0.95rem;
  color: var(--accent);
  font-weight: 600;
  min-width: 80px;
  text-align: right;
}

.delete-btn {
  padding: 8px 12px;
  border: none;
  border-radius: 8px;
  background: var(--delete);
  color: #fff;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.delete-btn:hover {
  background: var(--delete-hover);
}

.delete-btn:focus-visible {
  outline: 3px solid var(--delete);
  outline-offset: 2px;
}

.delete-btn:active {
  transform: scale(0.95);
}

.empty-msg {
  text-align: center;
  color: #888;
  font-style: italic;
  padding: 24px 0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 480px) {
  .card {
    padding: var(--spacing);
  }

  h1 {
    font-size: 1.4rem;
  }

  .habit-item {
    flex-direction: column;
    align-items: stretch;
  }

  .streak {
    text-align: left;
  }

  .day-boxes {
    justify-content: center;
  }
}

(function () {
  'use strict';

  const DAYS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
  const STORAGE_KEY = 'pixel-habit-tracker';

  let habits = loadHabits();

  const form = document.getElementById('habit-form');
  const input = document.getElementById('habit-input');
  const list = document.getElementById('habit-list');
  const emptyMsg = document.getElementById('empty-msg');

  function loadHabits() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch {
      return [];
    }
  }

  function saveHabits() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(habits));
    } catch {
      /* ignore */
    }
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  function calculateStreak(habit) {
    const today = new Date();
    let streak = 0;
    for (let i = 0; i < 7; i++) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const dayIndex = (d.getDay() + 6) % 7; // Monday = 0
      if (habit.days[dayIndex]) {
        streak++;
      } else {
        break;
      }
    }
    return streak;
  }

  function render() {
    list.innerHTML = '';
    emptyMsg.style.display = habits.length ? 'none' : 'block';

    habits.forEach(function (habit) {
      const item = document.createElement('div');
      item.className = 'habit-item';

      const name = document.createElement('span');
      name.className = 'habit-name';
      name.textContent = habit.name;
      item.appendChild(name);

      const boxes = document.createElement('div');
      boxes.className = 'day-boxes';
      boxes.setAttribute('role', 'group');
      boxes.setAttribute('aria-label', 'Days for ' + habit.name);

      DAYS.forEach(function (label, index) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'day-box' + (habit.days[index] ? ' done' : '');
        btn.textContent = label;
        btn.setAttribute('aria-label', 'Toggle ' + ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][index] + ' for ' + habit.name);
        btn.setAttribute('aria-pressed', habit.days[index] ? 'true' : 'false');
        btn.addEventListener('click', function () {
          habit.days[index] = !habit.days[index];
          saveHabits();
          render();
        });
        boxes.appendChild(btn);
      });

      item.appendChild(boxes);

      const streak = document.createElement('span');
      streak.className = 'streak';
      const s = calculateStreak(habit);
      streak.textContent = s + ' day' + (s === 1 ? '' : 's') + ' streak';
      item.appendChild(streak);

      const del = document.createElement('button');
      del.type = 'button';
      del.className = 'delete-btn';
      del.textContent = 'Delete';
      del.setAttribute('aria-label', 'Delete ' + habit.name);
      del.addEventListener('click', function () {
        habits = habits.filter(function (h) { return h.id !== habit.id; });
        saveHabits();
        render();
      });
      item.appendChild(del);

      list.appendChild(item);
    });
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    const name = input.value.trim();
    if (!name) return;

    habits.push({
      id: generateId(),
      name: name,
      days: [false, false, false, false, false, false, false]
    });

    input.value = '';
    saveHabits();
    render();
    input.focus();
  });

  render();
})();
